test("vesselLabel", () => {
  assert.throws(() => m.vesselLabel('   '));
  assert.equal(m.vesselLabel('  Ada '), 'Ada');
});

test("uniquePortCalls", () => {
  assert.deepEqual(m.uniquePortCalls(['B', 'A', 'B', 'C']), ['B', 'A', 'C']);
  assert.deepEqual(m.uniquePortCalls(['A', 'B', 'A']), ['A', 'B']);
  assert.deepEqual(m.uniquePortCalls([]), []);
});
